from pdfminer.high_level import extract_text, extract_pages
from pdfminer.layout import LTTextContainer, LTTextBox, LTTextLine, LTTextBoxHorizontal

def extract_verbose(filepath):
    pages = list(extract_pages(filepath))
    for i, page in enumerate(pages):
        print(f'=== Page {i} ===')
        for element in page:
            if hasattr(element, 'get_text') and element.get_text():
                txt = element.get_text().strip()
                if txt:
                    print(f'  [{type(element).__name__}] y={element.y0:.1f} "{txt}"')
        print()

extract_verbose('exams/resultado_beta.pdf')
